const DATE = SymbolCtor('date');
const YM = SymbolCtor('ym');
const MD = SymbolCtor('md');
const TIME_FMT = SymbolCtor('time');
const DATETIME = SymbolCtor('datetime');
const INST = SymbolCtor('instant');
const TZ_CANONICAL = SymbolCtor('timezone-canonical');
const TZ_ORIGINAL = SymbolCtor('timezone-original');
const CAL_ID = SymbolCtor('calendar-id');
const LOCALE = SymbolCtor('locale');
const OPTIONS = SymbolCtor('options');

// Construction of built-in Intl.DateTimeFormat objects is sloooooow,
// so we'll only create those instances when we need them.
// See https://bugs.chromium.org/p/v8/issues/detail?id=6528
function getSlotLazy(obj, slot) {
  let val = GetSlot(obj, slot);
  if (typeof val === 'function') {
    val = new IntlDateTimeFormat(GetSlot(obj, LOCALE), val(GetSlot(obj, OPTIONS)));
    SetSlot(obj, slot, val);
  }
  return val;
}

// Return the value of the corresponding part from formatToParts() output
function findPart(parts, expectedType) {
  for (let ix = 0; ix < parts.length; ix++) {
    if (parts[ix].type === expectedType) return parts[ix].value;
  }
  /* c8 ignore next */ assertNotReached('findPart() should only be used when the part is expected');
}

function adjustRenderedDay(polyfilledFormatter, realFormatter, originalEpochMs, renderedValue, dayAdjust) {
  if (dayAdjust === 0) return renderedValue;
  let day = +renderedValue;
  if (!NumberIsNaN(day)) return StringCtor(day - dayAdjust);

  // If the day isn't given in Arabic numerals, re-do the format in a
  // way that's parseable by StringToNumber
  const options = ES.Call(IntlDateTimeFormatPrototypeResolvedOptions, realFormatter, []);
  const originalNumberingSystem = options.numberingSystem;
  options.numberingSystem = 'latn';
  const parseableFormatter = new IntlDateTimeFormat('en', options);
  const parseableParts = ES.Call(IntlDateTimeFormatPrototypeFormatToParts, parseableFormatter, [originalEpochMs]);
  const parseableDay = findPart(parseableParts, 'day');
  day = +parseableDay;

  // Reformat the day in the target format's numeral system
  const numberFormatter = new IntlNumberFormat(GetSlot(polyfilledFormatter, LOCALE), {
    numberingSystem: originalNumberingSystem
  });
  const boundFormat = ES.Call(IntlNumberFormatPrototypeGetFormat, numberFormatter, []);
  return ES.Call(boundFormat, numberFormatter, [day - dayAdjust]);
}

function adjustRenderedWeekday(polyfilledFormatter, realFormatter, originalEpochMs, renderedValue, dayAdjust) {
  if (dayAdjust === 0) return renderedValue;
  // The weekday, if present, needs to be adjusted as well. Use ZonedDateTime as
  // a convenient way to get the ordinal weekday.
  const options = ES.Call(IntlDateTimeFormatPrototypeResolvedOptions, realFormatter, []);
  const zdt = ES.CreateTemporalZonedDateTime(bigInt(originalEpochMs).multiply(1e6), options.timeZone);
  options.timeZone = 'UTC';
  const weekdayFormatter = new IntlDateTimeFormat(GetSlot(polyfilledFormatter, LOCALE), options);
  // Weekday of 1970-01-01 is 4 (Thursday)
  const weekdayParts = ES.Call(IntlDateTimeFormatPrototypeFormatToParts, weekdayFormatter, [
    (zdt.dayOfWeek - dayAdjust - 4) * ES.DAY_MS
  ]);
  return findPart(weekdayParts, 'weekday');
}

function internalCreateDateTimeFormat(dtf, locale, options, required) {
  const hasOptions = typeof options !== 'undefined';
  if (hasOptions) {
    // Read all the options in the expected order, perform expected conversions
    // and validations, and copy them to a null-prototype object with which we
    // can do further operations unobservably
    const props = [
      ['localeMatcher', 'string', ['lookup', 'best fit']],
      ['calendar', 'string', null],
      ['numberingSystem', 'string', null],
      ['hour12', 'boolean'],
      ['hourCycle', 'string', ['h11', 'h12', 'h23', 'h24']],
      ['timeZone', 'string', null],
      ['weekday', 'string', ['narrow', 'short', 'long']],
      ['era', 'string', ['narrow', 'short', 'long']],
      ['year', 'string', ['2-digit', 'numeric']],
      ['month', 'string', ['2-digit', 'numeric', 'narrow', 'short', 'long']],
      ['day', 'string', ['2-digit', 'numeric']],
      ['dayPeriod', 'string', ['narrow', 'short', 'long']],
      ['hour', 'string', ['2-digit', 'numeric']],
      ['minute', 'string', ['2-digit', 'numeric']],
      ['second', 'string', ['2-digit', 'numeric']],
      ['fractionalSecondDigits', 'number', 1, 3],
      ['timeZoneName', 'string', ['short', 'long', 'shortOffset', 'longOffset', 'shortGeneric', 'longGeneric']],
      ['formatMatcher', 'string', ['basic', 'best fit']],
      ['dateStyle', 'string', ['full', 'long', 'medium', 'short']],
      ['timeStyle', 'string', ['full', 'long', 'medium', 'short']]
    ];
    options = ES.ToObject(options);
    const newOptions = ObjectCreate(null);
    for (let i = 0; i < props.length; i++) {
      const entry = props[i];
      const prop = entry[0];
      let value = options[prop];
      if (value !== undefined) {
        const conversionHint = entry[1];
        switch (conversionHint) {
          case 'string':
            {
              value = ES.ToString(value);
              const allowed = entry[2];
              if (allowed !== null && !ES.Call(ArrayPrototypeIncludes, allowed, [value])) {
                throw new RangeError(`Value ${value} out of range for Intl.DateTimeFormat options property ${prop}`);
              }
            }
            break;
          case 'number':
            {
              value = ES.ToNumber(value);
              const minimum = entry[2];
              const maximum = entry[3];
              if (!NumberIsFinite(value) || value < minimum || value > maximum) {
                throw new RangeError(`${prop} value is out of range`);
              }
            }
            break;
          case 'boolean': // nothing observable, handle in real DTF constructor
        }
        newOptions[prop] = value;
      }
    }
    options = newOptions;
  } else {
    options = ObjectCreate(null);
  }

  let original = new IntlDateTimeFormat(locale, options);
  let ro = ES.Call(IntlDateTimeFormatPrototypeResolvedOptions, original, []);

  // If the original Intl.DateTimeFormat resolvedOptions isn't new enough to
  // reject the unshipped IDs, log a warning and re-do it. Fallbacks are based
  // on discussion https://github.com/tc39/proposal-intl-era-monthcode/issues/29
  const fallbacks = [
    ['islamic', 'islamic-tbla'],
    ['islamic-rgsa', 'islamic-umalqura']
  ];
  for (let ix = 0; ix < fallbacks.length; ix++) {
    const id = fallbacks[ix][0];
    const substitute = fallbacks[ix][1];
    if (ro.calendar === id) {
      options.calendar = substitute;
      warn(
        `"${id}" calendar ID does not specify the calendar algorithm. "${substitute}" was used. ` +
          'Please specify one of "islamic-umalqura", "islamic-tbla", or "islamic-civil" explicitly.'
      );
      original = new IntlDateTimeFormat(locale, options);
      ro = ES.Call(IntlDateTimeFormatPrototypeResolvedOptions, original, []);
    }
  }

  CreateSlots(dtf);

  // DateTimeFormat instances are very expensive to create. Therefore, they will
  // be lazily created only when needed, using the locale and options provided.
  // But it's possible for callers to mutate those inputs before lazy creation
  // happens. For this reason, we clone the inputs instead of caching the
  // original objects. To avoid the complexity of deep cloning any inputs that
  // are themselves objects (e.g. the locales array, or options property values
  // that will be coerced to strings), we rely on `resolvedOptions()` to do the
  // coercion and cloning for us. Unfortunately, we can't just use the resolved
  // options as-is because our options-amending logic adds additional fields if
  // the user doesn't supply any unit fields like year, month, day, hour, etc.
  // Therefore, we limit the properties in the clone to properties that were
  // present in the original input.
  if (hasOptions) {
    const clonedResolved = ObjectAssign(ObjectCreate(null), ro);
    for (const prop in clonedResolved) {
      if (!ES.HasOwnProperty(options, prop)) delete clonedResolved[prop];
    }
    // hour12/hourCycle don't show up in resolvedOptions() unless the chosen
    // format includes an hour component, so copy them explicitly in case they
    // would otherwise be lost
    clonedResolved.hour12 = options.hour12;
    clonedResolved.hourCycle = options.hourCycle;
    SetSlot(dtf, OPTIONS, clonedResolved);
  } else {
    SetSlot(dtf, OPTIONS, options);
  }

  SetSlot(dtf, LOCALE, ro.locale);
  SetSlot(dtf, ORIGINAL, original);
  SetSlot(dtf, TZ_CANONICAL, ro.timeZone);
  SetSlot(dtf, CAL_ID, ro.calendar);

  if (options.dateStyle !== undefined || options.timeStyle !== undefined) {
    if (options.dateStyle !== undefined) {
      if (required === 'time') {
        throw new TypeErrorCtor('toLocaleString of Temporal.PlainTime does not support dateStyle option');
      }
      SetSlot(dtf, DATE, dateAmend);
      SetSlot(dtf, YM, yearMonthAmend);
      SetSlot(dtf, MD, monthDayAmend);
    } else {
      SetSlot(dtf, DATE, null);
      SetSlot(dtf, YM, null);
      SetSlot(dtf, MD, null);
    }
    if (options.timeStyle !== undefined) {
      if (required === 'date') {
        throw new TypeErrorCtor('toLocaleString of a Temporal date type does not support timeStyle option');
      }
      SetSlot(dtf, TIME_FMT, timeAmend);
    } else {
      SetSlot(dtf, TIME_FMT, null);
    }
  } else {
    SetSlot(dtf, DATE, dateAmend);
    SetSlot(dtf, YM, yearMonthAmend);
    SetSlot(dtf, MD, monthDayAmend);
    SetSlot(dtf, TIME_FMT, timeAmend);
  }

  SetSlot(dtf, DATETIME, datetimeAmend);
  SetSlot(dtf, INST, instantAmend);

  // Save the original time zone, for a few reasons:
  // - Clearer error messages
  // - More clearly follows the spec for InitializeDateTimeFormat
  // - Because it follows the spec more closely, will make it easier to integrate
  //   support of offset strings and other potential changes like proposal-canonical-tz.
  const timeZoneOption = hasOptions ? options.timeZone : undefined;
  if (timeZoneOption === undefined) {
    SetSlot(dtf, TZ_ORIGINAL, ro.timeZone);
  } else {
    const id = ES.ToString(timeZoneOption);
    if (id.startsWith('−')) {
      // The initial (Node 23) implementation of offset time zones allowed use
      // of the Unicode minus sign, which was disallowed by a later spec change.
      throw new RangeError('Unicode minus (U+2212) is not supported in time zone offsets');
    }
    // store a normalized identifier
    SetSlot(dtf, TZ_ORIGINAL, ES.ToTemporalTimeZoneIdentifier(id));
  }
}

class DateTimeFormatImpl {
  constructor(locales = undefined, options = undefined) {
    internalCreateDateTimeFormat(this, locales, options, 'any');
  }

  get format() {
    if (!HasSlot(this, ORIGINAL)) throw new TypeErrorCtor('invalid receiver');
    const boundFormat = (...args) => ES.Call(format, this, args);
    ObjectDefineProperties(boundFormat, {
      length: { value: 1, enumerable: false, writable: false, configurable: true },
      name: { value: '', enumerable: false, writable: false, configurable: true }
    });
    return boundFormat;
  }

  formatRange(a, b) {
    if (!HasSlot(this, ORIGINAL)) throw new TypeErrorCtor('invalid receiver');
    return ES.Call(formatRange, this, [a, b]);
  }

  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  formatToParts(datetime, ...rest) {
    if (!HasSlot(this, ORIGINAL)) throw new TypeErrorCtor('invalid receiver');
    const args = ES.Call(ArrayPrototypeSlice, arguments, []);
    return ES.Call(formatToParts, this, args);
  }

  formatRangeToParts(a, b) {
    if (!HasSlot(this, ORIGINAL)) throw new TypeErrorCtor('invalid receiver');
    return ES.Call(formatRangeToParts, this, [a, b]);
  }

  resolvedOptions() {
    if (!HasSlot(this, ORIGINAL)) throw new TypeErrorCtor('invalid receiver');
    return ES.Call(resolvedOptions, this, []);
  }
}

if (!('formatToParts' in IntlDateTimeFormat.prototype)) {
  delete DateTimeFormatImpl.prototype.formatToParts;
}

if (!('formatRangeToParts' in IntlDateTimeFormat.prototype)) {
  delete DateTimeFormatImpl.prototype.formatRangeToParts;
}

// A non-class constructor is needed because Intl.DateTimeFormat must be able to
// be called without 'new'
export function DateTimeFormat(locales = undefined, options = undefined) {
  return new DateTimeFormatImpl(locales, options);
}
DateTimeFormatImpl.prototype.constructor = DateTimeFormat;

ObjectDefineProperty(DateTimeFormat, 'prototype', {
  value: DateTimeFormatImpl.prototype,
  writable: false,
  enumerable: false,
  configurable: false
});
DateTimeFormat.supportedLocalesOf = IntlDateTimeFormat.supportedLocalesOf;
MakeIntrinsicClass(DateTimeFormat, 'Intl.DateTimeFormat');

// This corresponds to the spec operation CreateDateTimeFormat in that it
// creates a new instance and does all the required initialization on it.
// However, most of the spec operation is in internalCreateDateTimeFormat() so
// that we can call it in the DateTimeFormat constructor, where we already have
// the uninitialized instance.
export function CreateDateTimeFormat(locales, options, required) {
  const instance = Object.create(DateTimeFormat.prototype);
  internalCreateDateTimeFormat(instance, locales, options, required);
  return instance;
}

function resolvedOptions() {
  const resolved = ES.Call(IntlDateTimeFormatPrototypeResolvedOptions, GetSlot(this, ORIGINAL), []);
  resolved.timeZone = GetSlot(this, TZ_ORIGINAL);
  return resolved;
}

// eslint-disable-next-line @typescript-eslint/no-unused-vars
function format(datetime, ...rest) {
  let { epochNs, formatter, dayAdjust = 0 } = extractOverrides(datetime, this);
  let formatArgs;
  if (formatter) {
    formatArgs = [ES.epochNsToMs(epochNs, 'floor')];
  } else {
    formatter = GetSlot(this, ORIGINAL);
    formatArgs = ES.Call(ArrayPrototypeSlice, arguments, []);
  }
  if (dayAdjust === 0) {
    // Happy path
    const boundFormat = ES.Call(IntlDateTimeFormatPrototypeGetFormat, formatter, []);
    return ES.Call(boundFormat, formatter, formatArgs);
  }

  // Special case for extreme dates, to avoid TimeClip restriction
  const parts = ES.Call(IntlDateTimeFormatPrototypeFormatToParts, formatter, formatArgs);
  let result = '';
  for (let ix = 0; ix < parts.length; ix++) {
    const { type, value } = parts[ix];
    if (type === 'day') {
      result += adjustRenderedDay(this, formatter, formatArgs[0], value, dayAdjust);
    } else if (type === 'weekday') {
      result += adjustRenderedWeekday(this, formatter, formatArgs[0], value, dayAdjust);
    } else {
      result += value;
    }
  }
  return result;
}

// eslint-disable-next-line @typescript-eslint/no-unused-vars
function formatToParts(datetime, ...rest) {
  let { epochNs, formatter, dayAdjust = 0 } = extractOverrides(datetime, this);
  let formatArgs;
  if (formatter) {
    formatArgs = [ES.epochNsToMs(epochNs, 'floor')];
  } else {
    formatter = GetSlot(this, ORIGINAL);
    formatArgs = ES.Call(ArrayPrototypeSlice, arguments, []);
  }
  const parts = ES.Call(IntlDateTimeFormatPrototypeFormatToParts, formatter, formatArgs);
  if (dayAdjust !== 0) {
    // Special case for extreme dates, to avoid TimeClip restriction
    for (let ix = 0; ix < parts.length; ix++) {
      const { type, value } = parts[ix];
      if (type === 'day') {
        parts[ix].value = adjustRenderedDay(this, formatter, formatArgs[0], value, dayAdjust);
      } else if (type === 'weekday') {
        parts[ix].value = adjustRenderedWeekday(this, formatter, formatArgs[0], value, dayAdjust);
      }
    }
  }
  return parts;
}

function formatRange(a, b) {
  if (a === undefined || b === undefined) {
    throw new TypeErrorCtor('Intl.DateTimeFormat.formatRange requires two values');
  }
  a = toDateTimeFormattable(a);
  b = toDateTimeFormattable(b);
  let formatArgs = [a, b];
  let formatter;
  let aDayAdjust = 0;
  let bDayAdjust = 0;
  if (isFormattableTemporalObject(a) || isFormattableTemporalObject(b)) {
    if (!sameTemporalType(a, b)) {
      throw new TypeErrorCtor('Intl.DateTimeFormat.formatRange accepts two values of the same type');
    }
    const aRecord = extractOverrides(a, this);
    const bRecord = extractOverrides(b, this);
    assert(bRecord.formatter == aRecord.formatter, 'formatters for same Temporal type should be identical');
    formatter = aRecord.formatter;
    formatArgs = [ES.epochNsToMs(aRecord.epochNs, 'floor'), ES.epochNsToMs(bRecord.epochNs, 'floor')];
    aDayAdjust = aRecord.dayAdjust ?? 0;
    bDayAdjust = bRecord.dayAdjust ?? 0;
  } else {
    formatter = GetSlot(this, ORIGINAL);
  }
  if (aDayAdjust !== 0 || bDayAdjust !== 0) {
    // Special case for extreme dates, to avoid TimeClip restriction
    const parts = ES.Call(IntlDateTimeFormatPrototypeFormatRangeToParts, formatter, formatArgs);
    let result = '';
    for (let ix = 0; ix < parts.length; ix++) {
      const { type, value, source } = parts[ix];
      const isStart = source === 'startRange';
      if (type === 'day') {
        result += adjustRenderedDay(
          this,
          formatter,
          formatArgs[isStart ? 0 : 1],
          value,
          isStart ? aDayAdjust : bDayAdjust
        );
      } else if (type === 'weekday') {
        result += adjustRenderedWeekday(
          this,
          formatter,
          formatArgs[isStart ? 0 : 1],
          value,
          isStart ? aDayAdjust : bDayAdjust
        );
      } else {
        result += value;
      }
    }
    return result;
  }
  return ES.Call(IntlDateTimeFormatPrototypeFormatRange, formatter, formatArgs);
}

function formatRangeToParts(a, b) {
  if (a === undefined || b === undefined) {
    throw new TypeErrorCtor('Intl.DateTimeFormat.formatRange requires two values');
  }
  a = toDateTimeFormattable(a);
  b = toDateTimeFormattable(b);
  let formatArgs = [a, b];
  let formatter;
  let aDayAdjust = 0;
  let bDayAdjust = 0;
  if (isFormattableTemporalObject(a) || isFormattableTemporalObject(b)) {
    if (!sameTemporalType(a, b)) {
      throw new TypeErrorCtor('Intl.DateTimeFormat.formatRangeToParts accepts two values of the same type');
    }
    const aRecord = extractOverrides(a, this);
    const bRecord = extractOverrides(b, this);
    assert(bRecord.formatter == aRecord.formatter, 'formatters for same Temporal type should be identical');
    formatter = aRecord.formatter;
    formatArgs = [ES.epochNsToMs(aRecord.epochNs, 'floor'), ES.epochNsToMs(bRecord.epochNs, 'floor')];
    aDayAdjust = aRecord.dayAdjust ?? 0;
    bDayAdjust = bRecord.dayAdjust ?? 0;
  } else {
    formatter = GetSlot(this, ORIGINAL);
  }
  const parts = ES.Call(IntlDateTimeFormatPrototypeFormatRangeToParts, formatter, formatArgs);
  if (aDayAdjust !== 0 || bDayAdjust !== 0) {
    // Special case for extreme dates, to avoid TimeClip restriction
    for (let ix = 0; ix < parts.length; ix++) {
      const { type, value, source } = parts[ix];
      const isStart = source === 'startRange';
      if (type === 'day') {
        parts[ix].value = adjustRenderedDay(
          this,
          formatter,
          formatArgs[isStart ? 0 : 1],
          value,
          isStart ? aDayAdjust : bDayAdjust
        );
      } else if (type === 'weekday') {
        parts[ix].value = adjustRenderedWeekday(
          this,
          formatter,
          formatArgs[isStart ? 0 : 1],
          value,
          isStart ? aDayAdjust : bDayAdjust
        );
      }
    }
  }
  return parts;
}

function amend(options = {}, amended = {}) {
  options = ObjectAssign({}, options);
  const props = [
    'era',
    'year',
    'month',
    'day',
    'hour',
    'minute',
    'second',
    'weekday',
    'dayPeriod',
    'timeZoneName',
    'dateStyle',
    'timeStyle'
  ];
  for (let i = 0; i < props.length; i++) {
    const opt = props[i];
    options[opt] = opt in amended ? amended[opt] : options[opt];
    if (options[opt] === false || options[opt] === undefined) delete options[opt];
  }
  return options;
}

function timeAmend(originalOptions) {
  const options = amend(originalOptions, {
    era: false,
    year: false,
    month: false,
    day: false,
    weekday: false,
    timeZoneName: false,
    dateStyle: false
  });
  if (options.timeStyle === 'long' || options.timeStyle === 'full') {
    // Try to fake what timeStyle should do if not printing the time zone name
    delete options.timeStyle;
    ObjectAssign(options, { hour: 'numeric', minute: '2-digit', second: '2-digit' });
  }
  if (!hasTimeOptions(options)) {
    if (hasAnyDateTimeOptions(originalOptions)) {
      throw new TypeErrorCtor(`cannot format Temporal.PlainTime with options [${ObjectKeys(originalOptions)}]`);
    }
    ObjectAssign(options, {
      hour: 'numeric',
      minute: 'numeric',
      second: 'numeric'
    });
  }
  options.timeZone = 'UTC';
  return options;
}

function yearMonthAmend(originalOptions) {
  // Try to fake what dateStyle should do for dates without a day. This is not
  // accurate for locales that always print the era
  const dateStyleHacks = {
    short: { year: '2-digit', month: 'numeric' },
    medium: { year: 'numeric', month: 'short' },
    long: { year: 'numeric', month: 'long' },
    full: { year: 'numeric', month: 'long' }
  };
  const options = amend(originalOptions, {
    day: false,
    hour: false,
    minute: false,
    second: false,
    weekday: false,
    dayPeriod: false,
    timeZoneName: false,
    timeStyle: false
  });
  if ('dateStyle' in options) {
    const style = options.dateStyle;
    delete options.dateStyle;
    ObjectAssign(options, dateStyleHacks[style]);
  }
  if (!('year' in options || 'month' in options)) {
    if (hasAnyDateTimeOptions(originalOptions)) {
      throw new TypeErrorCtor(`cannot format PlainYearMonth with options [${ObjectKeys(originalOptions)}]`);
    }
    ObjectAssign(options, { year: 'numeric', month: 'numeric' });
  }
  options.timeZone = 'UTC';
  return options;
}

function monthDayAmend(originalOptions) {
  // Try to fake what dateStyle should do for dates without a day
  const dateStyleHacks = {
    short: { month: 'numeric', day: 'numeric' },
    medium: { month: 'short', day: 'numeric' },
    long: { month: 'long', day: 'numeric' },
    full: { month: 'long', day: 'numeric' }
  };
  const options = amend(originalOptions, {
    era: false,
    year: false,
    hour: false,
    minute: false,
    second: false,
    weekday: false,
    dayPeriod: false,
    timeZoneName: false,
    timeStyle: false
  });
  if ('dateStyle' in options) {
    const style = options.dateStyle;
    delete options.dateStyle;
    ObjectAssign(options, dateStyleHacks[style]);
  }
  if (!('month' in options || 'day' in options)) {
    if (hasAnyDateTimeOptions(originalOptions)) {
      throw new TypeErrorCtor(`cannot format PlainMonthDay with options [${ObjectKeys(originalOptions)}]`);
    }
    ObjectAssign(options, { month: 'numeric', day: 'numeric' });
  }
  options.timeZone = 'UTC';
  return options;
}

function dateAmend(originalOptions) {
  const options = amend(originalOptions, {
    hour: false,
    minute: false,
    second: false,
    dayPeriod: false,
    timeZoneName: false,
    timeStyle: false
  });
  if (!hasDateOptions(options)) {
    if (hasAnyDateTimeOptions(originalOptions)) {
      throw new TypeErrorCtor(`cannot format PlainDate with options [${ObjectKeys(originalOptions)}]`);
    }
    ObjectAssign(options, {
      year: 'numeric',
      month: 'numeric',
      day: 'numeric'
    });
  }
  options.timeZone = 'UTC';
  return options;
}

function datetimeAmend(originalOptions) {
  const options = amend(originalOptions, { timeZoneName: false });
  if (options.timeStyle === 'long' || options.timeStyle === 'full') {
    // Try to fake what timeStyle should do if not printing the time zone name
    delete options.timeStyle;
    ObjectAssign(options, { hour: 'numeric', minute: '2-digit', second: '2-digit' });

    // If moving to a fake timeStyle while dateStyle is present, we also have to
    // move to a fake dateStyle. dateStyle is mutually exclusive with hour etc.
    if (options.dateStyle) {
      const dateStyleHacks = {
        short: { year: 'numeric', month: 'numeric', day: 'numeric' },
        medium: { year: 'numeric', month: 'short', day: 'numeric' },
        long: { year: 'numeric', month: 'long', day: 'numeric' },
        full: { year: 'numeric', month: 'long', day: 'numeric', weekday: 'long' }
      };
      ObjectAssign(options, dateStyleHacks[options.dateStyle]);
      delete options.dateStyle;
    }
  }
  if (!hasTimeOptions(options) && !hasDateOptions(options)) {
    if (hasAnyDateTimeOptions(originalOptions)) {
      throw new TypeErrorCtor(`cannot format PlainDateTime with options [${ObjectKeys(originalOptions)}]`);
    }
    ObjectAssign(options, {
      year: 'numeric',
      month: 'numeric',
      day: 'numeric',
      hour: 'numeric',
      minute: 'numeric',
      second: 'numeric'
    });
  }
  options.timeZone = 'UTC';
  return options;
}

function instantAmend(options) {
  if (!hasTimeOptions(options) && !hasDateOptions(options)) {
    options = ObjectAssign({}, options, {
      year: 'numeric',
      month: 'numeric',
      day: 'numeric',
      hour: 'numeric',
      minute: 'numeric',
      second: 'numeric'
    });
  }
  return options;
}

function hasDateOptions(options) {
  return 'year' in options || 'month' in options || 'day' in options || 'weekday' in options || 'dateStyle' in options;
}

function hasTimeOptions(options) {
  return (
    'hour' in options ||
    'minute' in options ||
    'second' in options ||
    'timeStyle' in options ||
    'dayPeriod' in options ||
    'fractionalSecondDigits' in options
  );
}

function hasAnyDateTimeOptions(originalOptions) {
  return hasDateOptions(originalOptions) || hasTimeOptions(originalOptions);
}

function isFormattableTemporalObject(obj) {
  return (
    ES.IsTemporalDate(obj) ||
    ES.IsTemporalTime(obj) ||
    ES.IsTemporalDateTime(obj) ||
    ES.IsTemporalZonedDateTime(obj) ||
    ES.IsTemporalYearMonth(obj) ||
    ES.IsTemporalMonthDay(obj) ||
    ES.IsTemporalInstant(obj)
  );
}

function toDateTimeFormattable(value) {
  if (isFormattableTemporalObject(value)) return value;
  return ES.ToNumber(value);
}

function sameTemporalType(x, y) {
  if (!isFormattableTemporalObject(x) || !isFormattableTemporalObject(y)) return false;
  if (ES.IsTemporalTime(x) && !ES.IsTemporalTime(y)) return false;
  if (ES.IsTemporalDate(x) && !ES.IsTemporalDate(y)) return false;
  if (ES.IsTemporalDateTime(x) && !ES.IsTemporalDateTime(y)) return false;
  if (ES.IsTemporalZonedDateTime(x) && !ES.IsTemporalZonedDateTime(y)) return false;
  if (ES.IsTemporalYearMonth(x) && !ES.IsTemporalYearMonth(y)) return false;
  if (ES.IsTemporalMonthDay(x) && !ES.IsTemporalMonthDay(y)) return false;
  if (ES.IsTemporalInstant(x) && !ES.IsTemporalInstant(y)) return false;
  return true;
}

// Allows formatting an epochMs value that will pass TimeClip in the original
// DateTimeFormat code, and then adjusting it afterwards
function getAdjustedEpochNanoseconds(isoDateTime) {
  const epochNs = ES.GetUTCEpochNanoseconds(isoDateTime);
  try {
    ES.ValidateEpochNanoseconds(epochNs);
  } catch (e) {
    if (!(e instanceof RangeErrorCtor)) throw e;
    const minAdjust = MathCeil(epochNs.abs().subtract(ES.NS_MAX).toJSNumber() / ES.DAY_NANOS);
    const dayAdjust = minAdjust * (epochNs.geq(0) ? -1 : 1);
    return {
      dayAdjust,
      epochNs: epochNs.add(dayAdjust * ES.DAY_NANOS)
    };
  }
  return { dayAdjust: 0, epochNs };
}

function extractOverrides(temporalObj, main) {
  if (ES.IsTemporalTime(temporalObj)) {
    const isoDateTime = {
      isoDate: { year: 1970, month: 1, day: 1 },
      time: GetSlot(temporalObj, TIME)
    };
    const formatter = getSlotLazy(main, TIME_FMT);
    if (!formatter) throw new TypeErrorCtor('cannot format PlainTime with only date options');
    return {
      epochNs: ES.GetUTCEpochNanoseconds(isoDateTime),
      formatter
    };
  }

  if (ES.IsTemporalYearMonth(temporalObj)) {
    const calendar = GetSlot(temporalObj, CALENDAR);
    const mainCalendar = GetSlot(main, CAL_ID);
    if (calendar !== mainCalendar) {
      throw new RangeErrorCtor(
        `cannot format PlainYearMonth with calendar ${calendar} in locale with calendar ${mainCalendar}`
      );
    }
    const isoDateTime = ES.CombineISODateAndTimeRecord(GetSlot(temporalObj, ISO_DATE), ES.NoonTimeRecord());
    const formatter = getSlotLazy(main, YM);
    if (!formatter) throw new TypeErrorCtor('cannot format PlainYearMonth with only time options');
    const { epochNs, dayAdjust } = getAdjustedEpochNanoseconds(isoDateTime);
    return {
      epochNs,
      formatter,
      dayAdjust
    };
  }

  if (ES.IsTemporalMonthDay(temporalObj)) {
    const calendar = GetSlot(temporalObj, CALENDAR);
    const mainCalendar = GetSlot(main, CAL_ID);
    if (calendar !== mainCalendar) {
      throw new RangeErrorCtor(
        `cannot format PlainMonthDay with calendar ${calendar} in locale with calendar ${mainCalendar}`
      );
    }
    const isoDateTime = ES.CombineISODateAndTimeRecord(GetSlot(temporalObj, ISO_DATE), ES.NoonTimeRecord());
    const formatter = getSlotLazy(main, MD);
    if (!formatter) throw new TypeErrorCtor('cannot format PlainMonthDay with only time options');
    return {
      epochNs: ES.GetUTCEpochNanoseconds(isoDateTime),
      formatter
    };
  }

  if (ES.IsTemporalDate(temporalObj)) {
    const calendar = GetSlot(temporalObj, CALENDAR);
    const mainCalendar = GetSlot(main, CAL_ID);
    if (calendar !== 'iso8601' && calendar !== mainCalendar) {
      throw new RangeErrorCtor(
        `cannot format PlainDate with calendar ${calendar} in locale with calendar ${mainCalendar}`
      );
    }
    const isoDateTime = ES.CombineISODateAndTimeRecord(GetSlot(temporalObj, ISO_DATE), ES.NoonTimeRecord());
    const formatter = getSlotLazy(main, DATE);
    if (!formatter) throw new TypeErrorCtor('cannot format PlainDate with only time options');
    const { epochNs, dayAdjust } = getAdjustedEpochNanoseconds(isoDateTime);
    return {
      epochNs,
      formatter,
      dayAdjust
    };
  }

  if (ES.IsTemporalDateTime(temporalObj)) {
    const calendar = GetSlot(temporalObj, CALENDAR);
    const mainCalendar = GetSlot(main, CAL_ID);
    if (calendar !== 'iso8601' && calendar !== mainCalendar) {
      throw new RangeErrorCtor(
        `cannot format PlainDateTime with calendar ${calendar} in locale with calendar ${mainCalendar}`
      );
    }
    const isoDateTime = GetSlot(temporalObj, ISO_DATE_TIME);
    const { epochNs, dayAdjust } = getAdjustedEpochNanoseconds(isoDateTime);
    return {
      epochNs,
      formatter: getSlotLazy(main, DATETIME),
      dayAdjust
    };
  }

  if (ES.IsTemporalZonedDateTime(temporalObj)) {
    throw new TypeErrorCtor(
      'Temporal.ZonedDateTime not supported in DateTimeFormat methods. Use toLocaleString() instead.'
    );
  }

  if (ES.IsTemporalInstant(temporalObj)) {
    return {
      epochNs: GetSlot(temporalObj, EPOCHNANOSECONDS),
      formatter: getSlotLazy(main, INST)
    };
  }

  return {};
}

function temporalDurationToCompatibilityRecord(duration) {
  const record = ObjectCreate(null);
  record.years = GetSlot(duration, YEARS);
  record.months = GetSlot(duration, MONTHS);
  record.weeks = GetSlot(duration, WEEKS);
  record.days = GetSlot(duration, DAYS);
  record.hours = GetSlot(duration, HOURS);
  record.minutes = GetSlot(duration, MINUTES);
  record.seconds = GetSlot(duration, SECONDS);
  record.milliseconds = GetSlot(duration, MILLISECONDS);
  record.microseconds = GetSlot(duration, MICROSECONDS);
  record.nanoseconds = GetSlot(duration, NANOSECONDS);
  return record;
}

export function ModifiedIntlDurationFormatPrototypeFormat(durationLike) {
  ES.Call(IntlDurationFormatPrototypeResolvedOptions, this); // brand check
  const duration = ES.ToTemporalDuration(durationLike);
  const record = temporalDurationToCompatibilityRecord(duration);
  return ES.Call(IntlDurationFormatPrototypeFormat, this, [record]);
}

if (IntlDurationFormatPrototype) {
  IntlDurationFormatPrototype.format = ModifiedIntlDurationFormatPrototypeFormat;
  IntlDurationFormatPrototype.formatToParts = function formatToParts(durationLike) {
    ES.Call(IntlDurationFormatPrototypeResolvedOptions, this); // brand check
    const duration = ES.ToTemporalDuration(durationLike);
    const record = temporalDurationToCompatibilityRecord(duration);
    return ES.Call(IntlDurationFormatPrototypeFormatToParts, this, [record]);
  };
}
